using namespace std;

void quickio() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr); 
    cout.tie(nullptr); 
}

const int maxn = 1e8 + 1;
vector <int> Prime;
bitset <maxn> vis;

void init(int n) {
    vis[1] = 1;
    for (int i = 2; i <= n; i++) {
        if (!vis[i])
            Prime.push_back(i); 
        for (auto p : Prime) {
            if (i * p > n)
                break;
            vis[i * p] = 1;
            if (i % p == 0)
                break;
        }
    }
}

bool check(int x) {
    int rev = 0;
    while (x > rev) {
        rev = rev * 10 + x % 10;
        x /= 10;
    }
    return (x == rev || x == rev / 10);
}

int main() {
    quickio();
    int a, b;
    cin >> a >> b;
    init(b);
    for (auto p : Prime)
        if (check(p) && p >= a)
            cout << p << '\n';
    return 0;
}
