inline void Move(int x, int y){ a[x][++len[x]] = a[y][len[y]]; b[x][len[x]] = b[y][len[y]]; --len[y]; q[++ans] = y * 65 + x; } 
inline void movenum(int x, int y, int z){ while(z--) Move(x, y); } 
inline void movecol(int x, int y, int z){ 
	int num = 0; for(int i = 1; i <= m; ++i) num += (b[x][i] == z);
	if(num == m) return; if(num > m / 2){
		movenum(n + 1, y, m - num);
