inline void Qsort(int l, int r){ 
	if(l == r) return; int mid = l + r >> 1, x = l, y = r;
	for(int i = l; i <= r; ++i) for(int j = 1; j <= m; ++j) b[i][j] = (a[i][j] > mid);
	while(x <= mid && y > mid){
