#define gc() (p1==p2&&(p2=(p1=buf)+fread(buf,1,rp,stdin),p1==p2)?EOF:*p1++)

using namespace std;
const int N=3e5+10;
const int rp=1e6+10;

int n,m,cnt,ans,dis[N],dp[N];
int dep[N],fa[N],siz[N],son[N],top[N],dfn[N]; 
struct node{int u,v,w;}e[N]; 
struct ask{int u,v,w,t;}p[N]; 
vector<Pii> vt[N];
char buf[rp],*p1=buf,*p2=buf;

inline int read()
{
	int x=0,f=1; char c=0;
	while(!isdigit(c)) {if(c=='-') f=-1; c=gc();}
	while(isdigit(c)) x=(x<<3)+(x<<1)+(c^48),c=gc();
	return x*f;
}

inline char read_ch()
{
	char c=0;
	while((!isalpha(c))&&(!isdigit(c))) c=gc();
	return c;
}

inline void dfs1(int x,int f)
{
	dep[x]=dep[f]+1; fa[x]=f; siz[x]=1; dfn[++cnt]=x; 
	for(auto a:vt[x])
		if(a.fi!=f)
		{
			dis[a.fi]=dis[x]+a.se;
			dfs1(a.fi,x); siz[x]+=siz[a.fi];
			if(siz[a.fi]>siz[son[x]]) son[x]=a.fi;
		}
}

inline void dfs2(int x,int tp)
{
	top[x]=tp;
	if(!son[x]) return; dfs2(son[x],tp);
	for(auto a:vt[x])
		if(a.fi!=fa[x]&&a.fi!=son[x]) dfs2(a.fi,a.fi);
} 

inline int lca(int u,int v)
{
	while(top[u]!=top[v])
	{
		if(dep[top[u]]<dep[top[v]]) swap(u,v);
		u=fa[top[u]];
	}
	if(dep[u]>dep[v]) swap(u,v);
	return u;
} 

inline bool cr(int x)
{
	int cnt=0,res=0; memset(dp,0,sizeof dp);
	for(int i=1;i<=m;++i)
		if(p[i].t>x) 
		{
			++cnt; res=max(res,p[i].t); dp[p[i].w]-=2;
			++dp[p[i].u]; ++dp[p[i].v]; 
		}
	if(!cnt) return 1;
	for(int i=n;i>=1;--i) dp[fa[dfn[i]]]+=dp[dfn[i]]; 
	for(int i=1;i<n;++i)
		if(dp[e[i].u]==cnt&&res-e[i].w<=x) return 1;
	return 0;
}

signed main()
{
	cin.tie(0)->sync_with_stdio(0);
	cin>>n>>m; int L=0,R=5e8,mi;
	for(int i=1;i<n;++i)
	{
		cin>>e[i].u>>e[i].v>>e[i].w;
		vt[e[i].u].push_back({e[i].v,e[i].w});
		vt[e[i].v].push_back({e[i].u,e[i].w});
	}
	for(int i=1;i<=m;++i) cin>>p[i].u>>p[i].v;
	dfs1(1,0); dfs2(1,1);
	for(int i=1;i<n;++i)
		if(dep[e[i].u]<dep[e[i].v]) swap(e[i].u,e[i].v);
	for(int i=1;i<=m;++i)
		p[i].w=lca(p[i].u,p[i].v),
		p[i].t=dis[p[i].u]+dis[p[i].v]-dis[p[i].w]-dis[p[i].w]; 
	while(L<=R) 
	{
		mi=(L+R)>>1;
		if(cr(mi)) R=mi-1,ans=mi;
		else L=mi+1;
	}
	cout<<ans;
	return 0;
}
