        "code": "#include <bits/stdc++.h>

const int N = 8000 + 7;
const int M = 800 + 7;

std::vector<int> e[N];
int bit[M][N], f[N][M], g[N][M], n, m;
int dfn[N], nfd[N], ed[N], cdfn, dep[N];

void add(int *bit, int x, int v) {
  while(x <= n) {
    bit[x] += v;
    x += x & -x;
  }
}

int ask(int *bit, int x) {
  int ret = 0;
  while(x) {
    ret += bit[x];
    x -= x & -x;
  }
  return ret;
}

void dfs(int x) {
  dfn[x] = ++cdfn;
  nfd[cdfn] = x;
  for(int v: e[x]) {
    dep[v] = dep[x] + 1;
    dfs(v);
  }
  ed[x] = cdfn;
  for(int i = 1; i <= dep[x]; ++i) {
    f[x][i] = g[x][i] = i;
    for(int v: e[x])
      g[x][i] += g[v][i];
    for(int v: e[x])
      f[x][i] = std::max(f[x][i], f[v][i + 1] + g[x][i] - g[v][i]);
    for(int v: e[x]) {
      add(bit[i], dfn[v], g[x][i] - g[v][i]);
      add(bit[i], ed[v] + 1, g[v][i] - g[x][i]);
    }
  }
  for(int j = dfn[x] + 1; j <= ed[x]; ++j) {
    int i = dep[nfd[j]] - dep[x] + 1;
    g[x][i - 1] = std::max(g[x][i - 1], ask(bit[i - 1], j) + f[nfd[j]][i]);
  }
}  

void solve() {
  scanf("%d%d", &n, &m);
  for(int i = 1; i <= n; ++i)
    e[i].clear();
  for(int i = 2, x; i <= n; ++i) {
    scanf("%d", &x);
    e[x].push_back(i);
  }
  memset(bit, 0, sizeof bit);
  cdfn = 0;
  dep[1] = 1;
  dfs(1);
  printf("%d\n", f[1][1]);
}

int main() {




  int cases;
  scanf("%d", &cases);

  while(cases--)
    solve();

  return 0;
}
