#include <vector>
#include <algorithm>

using namespace std;

const int N = 200005;
vector<int> to[N];
int h[N], lh[N], son[N];
int fa[N][18], top[N], mp[N], tot;
info e[N];
vector<info> dp[N], lson[N];

info mr(info x, info y) {
	if (isempty(x))
		return y;
	if (isempty(y))
		return x;
	return MR(x, y);
}
info mc(info x, info y) {
	if (isempty(x))
		return y;
	if (isempty(y))
		return x;
	return MC(x, y);
}

info getv(vector<info> &a, int p) { return a.empty() ? emptyinfo : a[min((int)a.size() - 1, p)]; }

vector<info> merge(vector<int> a, vector<vector<info>> b, int m = -1) {
	static info v[N];
	static int l[N], r[N];
	int n = a.size();
	if (m == -1)
		m = 1 << 30;

	if (n == 1 && b[0].size() <= 1)
		return {emptyinfo};

	vector<info> f{emptyinfo};
	v[0] = emptyinfo;
	for (int i = 1; i != n; i++)
		l[i] = i - 1, r[i] = i + 1, v[i] = e[max(a[i - 1], a[i])];
	r[0] = 1, l[0] = n;
	r[n] = 0, l[n] = n - 1;

	for (int i = 0; i != n; i++)
		if (b[i].empty())
			b[i].push_back(emptyinfo);

	int bg = 0;
	auto del = [&](int x) {
		l[r[x]] = l[x], r[l[x]] = r[x];
		if (x == bg)
			bg = r[x];
		v[x] = mr(v[x], b[x].back());
		if (x)
			v[r[x]] = mc(v[x], v[r[x]]);
		else
			v[r[x]] = mr(v[r[x]], v[x]);
	};

	if(b[0].size() <= 1)
		del(0);

	for (int len = 1; len <= m; len++) {
		info x = emptyinfo;
		for (int i = bg; i <= len && i < n; i = r[i]) {
			if (len - i == (int)b[i].size() - 1 && r[i] <= len && i != n - 1) {
				del(i);
				continue;
			}
			if (l[i])
				x = mc(x, v[i]);
			else
				x = mr(v[i], x);
