		int mid = (l + r) >> 1;
		if (x > mid)
			return query(i << 1 | 1, mid + 1, r, x, d);
		pair<info, bool> tp = query(i << 1, l, mid, x, d);
		if (tp.second)
			return tp;
		if (x + d > rh[i])
			return {emptyinfo, 0};
		return {mr(getv(vl[i], d + mid - x + 1), getv(vr[i], x + d - mid - 1)), 1};
	}

	info query(int x, int d) { return query(1, 0, a.size() - 1, x, d).first; }
}seg[N];

