using namespace std;
#define maxn 23
#define mod 1000000007
int n,m,k;
int qp(int x,int y) {
	int res=1;
	while(y) {
		if(y&1)res=1ll*res*x%mod;
		x=1ll*x*x%mod;
		y>>=1;
	}
	return res;
}
int inv(int x) {
	return qp(x,mod-2);
}
int U;
int fac[210],invfac[210];
#define maxS 36888
#define hav(S,i) (((S)>>((i)-1))&1)
int g[maxS];
int in[maxn],out[maxn];
inline void add(int &x,int y) {
	x+=y;
	if(x<0)x+=mod;
	if(x>=mod)x-=mod;
}
#define rep(x,qwq,qaq) for(int (x)=(qwq);(x)<=(qaq);++(x))
void init_g() {
	g[0]=1;
	rep(S,1,U) {
		rep(i,1,n) {
			if(hav(S,i)) {
				if(out[i]&S)continue;
				add(g[S],g[(S^(1<<(i-1)))]);
			}
		}
	}
}
int In[maxS],Out[maxS];
int h[maxS][maxn];
int ppc[maxS];
void init_h() {
	rep(S,1,U) {
		ppc[S]=ppc[S>>1]+(S&1);
		rep(i,1,n) {
			if(hav(S,i))In[S]|=in[i],Out[S]|=out[i];
		}
	}
	h[0][0]=1;
	rep(S,1,U){
		for(int T=S; T; T=S&(T-1)) {
			if((In[T]&(S^T))||(Out[T]&(S^T)))continue;
			rep(j,0,ppc[S^T]) {
				add(h[S][j+1],1ll*h[S^T][j]*g[T]%mod);
			}
		}
	}
}
int f[maxS][maxn];
int K[maxS];
int ans;
void init_f(){
	rep(i,0,n)K[i]=(i&1?1:-1);
	f[0][0]=1;
	rep(S,1,U){
		for(int T=S;T;T=S&(T-1)){
			if(Out[S^T]&T)continue;
			rep(i,1,ppc[S]){
				rep(j,0,i-1){
					add(f[S][i],1ll*K[i-j]*f[S^T][j]*h[T][i-j]%mod*invfac[i-j]%mod);
				}
			}
		}
	}

}
int C(int x,int y) {
	if(x<y||x<0||y<0)return 0;
	return 1ll*fac[x]*invfac[y]%mod*invfac[x-y]%mod;
}
int u,v;
int main() {


	ios::sync_with_stdio(false);
	cin.tie(0),cout.tie(0);
	cin>>n>>m>>k;
	++k;
	fac[0]=invfac[0]=1;
	U=(1<<n)-1;
	rep(i,1,200)fac[i]=1ll*fac[i-1]*i%mod;
	rep(i,1,200)invfac[i]=inv(fac[i]);
	rep(i,1,m) {
		cin>>u>>v;
		out[u]|=(1<<(v-1));
		in[v]|=(1<<(u-1));
	}
	init_g();
	init_h();
	init_f();
	rep(i,1,k)add(ans,1ll*f[U][i]*C(k,i)%mod*fac[i]%mod);
	ans=1ll*ans*inv(1ll*fac[n]*C(n+k-1,k-1)%mod)%mod;
	cout<<ans;
	return 0;
}
