            ans.push_back(a[i].c - max(a[i].a, a[i].b));
    }
    sort(ans.begin(), ans.end());
    int i = 0;
    while(cnt1 > n/2)
        res -= ans[i++], cnt1--;
    while(cnt2 > n/2)
        res -= ans[i++], cnt2--;
    while(cnt3 > n/2)
        res -= ans[i++], cnt3--;
