#include "perm.h"
#include<set> 

using namespace std;

void init(int c, int t){
	return;
}

vector<int> perm(int n){
	vector<int> ans, r;
	vector<bool> vis;
	set<int> st;
	for(int i = 1; i <= n; i++) vis.push_back(0);
	int lst = 1e9, res, zero_pos = -1;
	for(int i = 1; i < n; i++){
		res = query(i, n-1);
		if(res < lst){
			ans.push_back(res);
			vis[res] = 1;
			lst = res;
		}
		else ans.push_back(-res);
		if(res == 0){
			zero_pos = i-1;
			break;
		}
	}
	if(zero_pos != -1){
		lst = 1e9;
		for(int i = n-2; i >= zero_pos; i--){
			res = query(0, i);
			if(res < lst){
				r.push_back(res);
				vis[res] = 1;
				lst = res;
			}
			else r.push_back(-res);
		}
		for(int i = (int)r.size()-1; i >= 0; i--) ans.push_back(r[i]);
	}
	else ans.push_back(0);
	for(int i = 0; i < n; i++){
		if(!vis[i]) st.insert(i);
	}
	for(int i = 0; i < n; i++){
		if(ans[i] < 0){
			auto it = st.upper_bound(-ans[i]);
			ans[i] = *it;
			st.erase(it);
		}
	}
	return ans;
}
