{
	LL s = pos - d;
	return v * v + 2 * a * s;
}
inline void pushup(int u)
{
	w[u] = min(w[u << 1], w[u << 1 | 1]);
}
void build(int u,int l,int r)
{
	if (l == r)
	{
		w[u] = 1000000;
		if (!l)
			w[u] = 0;
		return;
	}
	int mid = (l + r) >> 1;
	build(u << 1, l, mid);
	build(u << 1 | 1, mid + 1, r);
	pushup(u);
}
void update(int u,int l,int r,int x,int v)
{
	if (l == r)
	{
		w[u] = v;
		return;
	}
	int mid = (l + r) >> 1;
	if (x <= mid)
		update(u << 1, l, mid, x, v);
	else
		update(u << 1 | 1, mid + 1, r, x, v);
	pushup(u);
}
