void chkmax(T &x, const T &y) {
  if (x < y) x = y;
}
template <typename T>
void chkmin(T &x, const T &y) {
  if (y < x) x = y;
}
constexpr int MAXN = 1e5 + 10, MOD = 998244353, INF = 0x3f3f3f3f;
void inc(int &x, int y) { x += y, x >= MOD && (x -= MOD); }
void dec(int &x, int y) { x -= y, x < 0 && (x += MOD); }
