} uu[N << 2];
inline void upd(int x, int t) {
    uu[ti[x]].tr = t;
    uu[ti[x] = ++tot] = (node){x, a[x], b[x], t, 100001};
}
vector<int> vec[N];
inline bool cmp(const node &x, const node &y) {
    return x.b > y.b;
}
