int jump(int x){
	int now = 0, sec = 0;
	for(int i = LOG - 1; i >= 0; -- i)
		if(now + st[i][x] <= n){
			now += st[i][x];
			sec += (1 << i);
			x = (x + st[i][x] - 1) % n + 1;
		}
	return sec;
}

signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);

