	for(int i = 1; i <= n; ++ i){
		while(tot < m && r < 2 * n)
			if(!(cnt[a[++ r]] ++))
				++ tot;
		st[0][i] = r - i + 1;
		if(!(-- cnt[a[i]]))
			-- tot;
	}

	for(int i = 1; i < LOG; ++ i)
		for(int j = 1; j <= n; ++ j){
			int to = (j + st[i - 1][j] - 1) % n + 1;
			st[i][j] = min(st[i - 1][j] + st[i - 1][to], INF);
		}

	int ans = 0;
	for(int i = 1; i <= n; ++ i)
		ans = max(ans, jump(i));

