const int maxn = 1000100;
const int mod = 998244353;

inline int qpow(int b, int p) {
	int res = 1;
	while (p) {
		if (p & 1) {
			res = 1ULL * res * b % mod;
		}
		b = 1ULL * b * b % mod;
		p >>= 1;
	}
	return res;
}

inline void fix(int &x) {
	x += ((x >> 31) & mod);
}

int n, m, K, a[maxn], b[maxn], c[maxn], pr[maxn / 10], mpr[maxn], tot, tt, phi[maxn], inv[maxn];
bool vis[maxn];
pii d[99];

void dfs(int d, int x, vector<int> &di) {
	if (d > tt) {
		di.pb(x);
		return;
	}
	for (int i = 0; i <= ::d[d].scd; ++i, x *= ::d[d].fst) {
		dfs(d + 1, x, di);
	}
}

inline vector<int> getd(int n) {
	vector<int> di;
	tt = 0;
	while (n > 1) {
		int t = mpr[n], k = 0;
		while (n % t == 0) {
			n /= t;
			++k;
		}
		d[++tt] = pii(t, k);
	}
	dfs(1, 1, di);
	return di;
}

inline int calc(int n, int m) {
	auto dn = getd(n), dm = getd(m);
	int ans = 0;
	for (int x : dn) {
		for (int y : dm) {
			int z = x * y / __gcd(x, y);
			fix(ans += 1ULL * phi[x] * phi[y] * qpow(c[z], n * m / z) % mod - mod);
		}
	}
	ans = 1ULL * ans * inv[n * m] % mod;
	return ans;
}

struct node {
	int n, m, q, x, y, l, w;
	node(int _n = 0, int _m = 0, int _q = 0, int _x = 0, int _y = 0, int _l = 0, int _w = 0) : n(_n), m(_m), q(_q), x(_x), y(_y), l(_l), w(_w) {}
} f[99999];

inline bool check(node &a, int x, int y) {
	x %= a.n;
	y %= a.m;
	if (x % a.x) {
		return 0;
	}
	int t = x / a.x;
	return a.y * t % a.m == y;
}

inline bool check(node &a, node &b) {
	if (a.n % b.n || a.m % b.m) {
		return 0;
	}
	return check(b, a.x, a.y);
}

void solve() {
	n = read();
	m = read();
	K = read();
	for (int i = 1; i <= K; ++i) {
		a[i] = read();
	}
	for (int i = 1; i <= K; ++i) {
		if (vis[i]) {
			continue;
		}
		int cnt = 0, u = i;
		do {
			++cnt;
			vis[u] = 1;
			u = a[u];
		} while (u != i);
		b[cnt] += cnt;
	}
	for (int i = 1; i <= n * m; ++i) {
		for (int j = i; j <= n * m; j += i) {
			c[j] += b[i];
		}
	}
	mems(vis, 0);
	phi[1] = inv[1] = 1;
	for (int i = 2; i <= n * m; ++i) {
		inv[i] = 1ULL * (mod - mod / i) * inv[mod % i] % mod;
	}
	for (int i = 2; i <= n * m; ++i) {
		if (!vis[i]) {
			pr[++tot] = i;
			mpr[i] = i;
			phi[i] = i - 1;
		}
		for (int j = 1; j <= tot && i * pr[j] <= n * m; ++j) {
			vis[i * pr[j]] = 1;
			mpr[i * pr[j]] = pr[j];
			if (i % pr[j] == 0) {
				phi[i * pr[j]] = phi[i] * pr[j];
				break;
			}
			phi[i * pr[j]] = phi[i] * (pr[j] - 1);
		}
	}
	tot = 0;
	for (int u = 1; u <= n; ++u) {
		if (n % u) {
			continue;
		}
		for (int v = 1; v <= m; ++v) {
			if (m % v) {
				continue;
			}
			int s = __gcd(u, v);
			for (int q = 0; q < s; ++q) {
				int g = __gcd(q, s);
				int x = u / s * g, y = v / s * q;
				int t1 = __gcd(s, __gcd(x, y));
				int cnt = u * v / s * g, t2 = cnt / t1;
				f[++tot] = node(u, v, q, x, y, cnt, calc(t1, t2));
			}
		}
	}
	sort(f + 1, f + tot + 1, [&](const node &a, const node &b) {
		return a.l < b.l;
	});
	int ans1 = 0, ans2 = 0;
	for (int i = 1; i <= tot; ++i) {
		for (int j = 1; j < i; ++j) {
			if (check(f[i], f[j])) {
				fix(f[i].w -= f[j].w);
			}
		}
		fix(ans1 += 1ULL * f[i].w * f[i].l % mod - mod);
		fix(ans2 += f[i].w - mod);
	}
	writeln(ans1);
	writeln(ans2);
}

int main() {
	int T = 1;

	while (T--) {
		solve();
	}
