    for(int i=1;i<=m;i++){
        int fu=find(edge[i].second.first),fv=find(edge[i].second.second);
        if(fu!=fv){
            fath[fv]=fu;
            edge[++tot]=edge[i];
            if(tot==n-1) break;
        }
    }
    for(int i=1;i<=k;i++){
        cost[i]=read();
        for(int j=1;j<=n;j++){
            edge[++tot]=make_pair(read(),make_pair(j,n+i));
        }
    }
    sort(edge+1,edge+1+tot);
    long long ans=1e18;
    for(int stat=0;stat<(1<<k);stat++){
        long long now=0;
        int num=0;
        for(int i=1;i<=k;i++){
            if((stat>>(i-1))&1){
                ++num,vis[i]=1;
                now+=cost[i];
            }
            else vis[i]=0;
        }
        for(int i=1;i<=n+k;i++) fath[i]=i;
        int need=n+num-1;
        for(int i=1;i<=tot;i++){
            int u=edge[i].second.first,v=edge[i].second.second;
            if(v>n and !vis[v-n]) continue;
            int fu=find(u),fv=find(v);
            if(fu!=fv){
                fath[fv]=fu;
                now+=edge[i].first;
                if(!(--need)) break;
            }
        }
        if(!need) ans=min(ans,now);
    }
    cout<<ans<<"\n";
    return 0;
}
