#include <iostream>
#include <vector>
using namespace std;

#define MAXN 200005

using ll = long long;

int n;

struct Rng
{
    ll l, r;
} a[MAXN], b[MAXN];

ll c[MAXN << 1];

vector<Rng> ad[MAXN << 1], de[MAXN << 1];

int cal(ll a, ll b, ll c)
{
    ll m = (a + b + c + 1) / 2;
    if (a >= m)
    {
        return -1;
    }
    if (a + b >= m)
    {
        return 0;
    }
    return 1;
}

bool calc(Rng l, ll m, Rng r)
{
    int s = cal(l.l, m, r.r), t = cal(l.r, m, r.l);
    return m && (s == 0 || t == 0 || s != t);
}

void solve()
{
    cin >> n;
    for (int i = 1; i <= n; i++)
    {
        cin >> a[i].l >> a[i].r >> b[i].l >> b[i].r;
        c[2 * i - 1] = b[i].l;
        c[2 * i] = b[i].r + 1;
    }
    sort(c + 1, c + 2 * n + 1);
    int idx = unique(c + 1, c + 2 * n + 1) - c - 1;
    Rng l{0, 0}, r{0, 0};
    ll m = 0;
    for (int i = 1; i <= n; i++)
    {
        b[i].l = lower_bound(c + 1, c + idx + 1, b[i].l) - c;
        b[i].r = lower_bound(c + 1, c + idx + 1, b[i].r + 1) - c;
        ad[b[i].l].push_back(a[i]);
        de[b[i].r].push_back(a[i]);
        r.l += a[i].l, r.r += a[i].r;
    }
    ll res = 0;
    for (int i = 1; i <= idx; i++)
    {
        for (auto [u, v] : ad[i])
        {
            m += v;
            r.l -= u, r.r -= v;
        }
        for (auto [u, v] : de[i])
        {
            m -= v;
            l.l += u, l.r += v;
        }
        if (calc(l, m, r))
        {
            res += c[i + 1] - c[i];
        }
        ad[i].clear();
        de[i].clear();
    }
    cout << res << endl;
}

int main()
{
    int t;
    cin >> t >> t;
    while (t--)
    {
        solve();
    }
    return 0;
}
